import Foundation

public struct WeatherClient {
    let baseURL: URL
    let session: URLSession

    public init(baseURL: URL = URL(string: "https://api.open-meteo.com/v1")!, session: URLSession = .shared) {
        self.baseURL = baseURL
        self.session = session
    }

    public func forecast(latitude: Double, longitude: Double) async throws -> Forecast {
        var components = URLComponents(url: baseURL.appendingPathComponent("forecast"), resolvingAgainstBaseURL: false)!
        components.queryItems = [
            .init(name: "latitude", value: String(latitude)),
            .init(name: "longitude", value: String(longitude)),
            .init(name: "hourly", value: "temperature_2m"),
        ]
        let (data, _) = try await session.data(from: components.url!)
        return try JSONDecoder().decode(Forecast.self, from: data)
    }
}

public struct Deck {
    public var cards: [Card]

    public static var standard: Deck {
        Deck(cards: Suit.allCases.flatMap { suit in Rank.allCases.map { Card(rank: $0, suit: suit) } })
    }

    public func shuffled<G: RandomNumberGenerator>(using rng: inout G) -> [Card] {
        cards.shuffled(using: &rng)
    }

    public func shuffled() -> [Card] {
        var rng = SystemRandomNumberGenerator()
        return shuffled(using: &rng)
    }
}

